<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import {api,APIError} from '../api';
import type {Validation} from '../types';
import type {SystemCatalogEntry} from '../systemTypes';
import {emptyDefinition,parseDefinition,type ComponentDefinition,type DefinitionRecord,type AspectEditorRequest,type DefinitionCompatibility,type AspectPort,endpointLabel,definitionStamp} from '../definitionTypes';
import {useWorkspaceDraft} from '../composables/useWorkspaceDraft';
import {useActionFeedback} from '../composables/useNotifications';
import StudioRibbon from './StudioRibbon.vue';
import DraftStatus from './DraftStatus.vue';
import CanvasInspector from './CanvasInspector.vue';
const emit=defineEmits<{openAspect:[request:AspectEditorRequest]}>();
const draft=ref<ComponentDefinition>(emptyDefinition());
const recovery=useWorkspaceDraft('component-definition',{draft});
const catalog=ref<SystemCatalogEntry[]>([]),records=ref<DefinitionRecord[]>([]);
const compatibility=ref<DefinitionCompatibility|null>(null);
const linkSource=ref(''),linkTarget=ref('');
const tab=ref('Aspects'),selected=ref(-1),settings=ref(false),libraryOpen=ref(true),search=ref('');
const busy=ref(''),error=ref(''),notice=ref(''),validation=ref<Validation|null>(null),importInput=ref<HTMLInputElement|null>(null);
useActionFeedback('Component definition',busy,notice,error);
const available=computed(()=>catalog.value.filter(e=>e.ready&&e.source==='installed-catalog'&&e.kind!=='definition'&&(e.name+' '+e.id+' '+e.kind).toLowerCase().includes(search.value.toLowerCase())));
const aspect=computed(()=>draft.value.aspects[selected.value]);
const installed=computed(()=>records.value.some(r=>definitionStamp(r.definition)===definitionStamp(draft.value)));
watch(draft,()=>{validation.value=null;},{deep:true});
watch(()=>JSON.stringify(draft.value.aspects),()=>{compatibility.value=null;linkSource.value='';linkTarget.value='';});
function addLink(){
 const source=compatibility.value?.ports[Number(linkSource.value)],target=compatibility.value?.ports[Number(linkTarget.value)];
 if(!source||!target||linkSource.value===''||linkTarget.value==='')return;
 const endpoint=(p:AspectPort)=>({slot:p.slot,interface:p.interface,port:p.port});
 (draft.value.links??=[]).push({id:'link-'+crypto.randomUUID().slice(0,8),source:endpoint(source),target:endpoint(target)});
 linkSource.value='';linkTarget.value='';
}

async function action(label:string,fn:()=>Promise<void>){if(busy.value)return;busy.value=label;error.value='';notice.value='';try{await recovery.ready;await fn();}catch(e){error.value=e instanceof Error?e.message:String(e);if(e instanceof APIError)validation.value={valid:false,issues:e.issues};}finally{busy.value='';}}
async function refresh(){const values=await Promise.all([api<SystemCatalogEntry[]>('/systems/catalog'),api<DefinitionRecord[]>('/systems/definitions')]);catalog.value=values[0];records.value=values[1];}
function reset(){draft.value=emptyDefinition();selected.value=-1;settings.value=false;tab.value='Aspects';notice.value='Empty component definition created';}
function load(record:DefinitionRecord){draft.value=parseDefinition(JSON.stringify(record.definition));selected.value=-1;settings.value=false;tab.value='Aspects';notice.value='Installed version opened. Change the version before installing modified content.';}
function add(entry:SystemCatalogEntry){const slot=entry.kind+'-'+crypto.randomUUID().slice(0,6);draft.value.aspects.push({slot,kind:entry.kind,id:entry.id,version:entry.version,digest:entry.digest});selected.value=draft.value.aspects.length-1;settings.value=false;}
function replace(event:Event){const input=event.target as HTMLSelectElement;const entry=catalog.value[Number(input.value)];if(entry?.ready&&aspect.value&&entry.source==='installed-catalog')draft.value.aspects[selected.value]={slot:aspect.value.slot,kind:entry.kind,id:entry.id,version:entry.version,digest:entry.digest};input.value='';}
async function validate(){await action('Validating component definition',async()=>{const snapshot=JSON.stringify(draft.value);const checked=await api<DefinitionCompatibility>('/systems/definitions/validate','POST',JSON.parse(snapshot));if(snapshot!==JSON.stringify(draft.value)){notice.value='Draft changed; validate again';return;}validation.value=checked;compatibility.value=checked;notice.value=checked.valid?'Dependencies and declared port links are compatible. Joint execution is not yet supported.':'';});}
async function install(){await action('Installing component version',async()=>{const snapshot=JSON.stringify(draft.value);await api<DefinitionRecord>('/systems/definitions','POST',JSON.parse(snapshot));await refresh();notice.value=snapshot===JSON.stringify(draft.value)?'Immutable component version installed. It is now available in System architecture.':'Snapshot installed; newer draft edits were retained.';});}
async function openAspect(){if(!aspect.value)return;const target={...aspect.value};const parent={id:draft.value.id,name:draft.value.name,version:draft.value.version,slot:target.slot};await action('Opening pinned aspect',async()=>{const result=await api<Omit<AspectEditorRequest,'context'>>('/systems/definitions/aspect','POST',target);emit('openAspect',{...result,context:{...parent,workspace:result.workspace}});});}
function locate(path:string){if(path.startsWith('links')){tab.value='Connections';settings.value=false;selected.value=-1;return;}const index=/aspects\[(\d+)\]/.exec(path);if(index){selected.value=Number(index[1]);settings.value=false;}else settings.value=true;tab.value='Aspects';}
function exportDefinition(){const url=URL.createObjectURL(new Blob([JSON.stringify(draft.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='component-definition.json';a.click();URL.revokeObjectURL(url);}
async function importDefinition(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];input.value='';if(!file)return;await action('Importing definition',async()=>{if(file.size>2_000_000)throw new Error('Definition exceeds 2 MB');const candidate=parseDefinition(await file.text());const checked=await api<DefinitionCompatibility>('/systems/definitions/validate','POST',candidate);if(!checked.valid)throw new APIError('Import needs exact installed dependencies. Current draft retained.',checked.issues);draft.value=candidate;selected.value=-1;settings.value=false;notice.value='Definition imported';});}
onMounted(()=>{void action('Loading component library',refresh);});
</script>

<template>
<section class="definition-workbench" :inert="recovery.status.value==='loading'" :aria-busy="!!busy">
 <StudioRibbon workspace="component-definition" :title="draft.name+' · '+draft.version" :active="tab" :structure="['Aspects','Connections']" :execution="['Versions']" @select="tab=$event;selected=-1;settings=false">
  <template #status><span>{{installed?'Installed exact version':'Definition draft'}}</span><DraftStatus :draft="recovery"/></template>
  <template #file><div class="commands"><button :disabled="!!busy" @click="reset">New component definition</button><button @click="exportDefinition">Export definition</button><button :disabled="!!busy" @click="importInput?.click()">Import definition</button><input ref="importInput" type="file" accept=".json,application/json" hidden @change="importDefinition"/></div></template>
  <template #help><p>A component definition owns named links to exact installed behavior, data, state, message and workflow versions. Its aspects remain reusable. Installing makes this definition version immutable.</p><p>Opening an aspect creates an editor draft. Install a new artifact version, return here, refresh the library, replace its pin and install a new component version. Edits never silently update installed systems. This manifest does not execute its aspects together.</p></template>
  <div class="commands"><button @click="settings=true;selected=-1;tab='Aspects'">Component identity</button><button :disabled="!!busy" @click="validate">Check compatibility</button><button :disabled="!!busy" @click="install">Install version</button><button :disabled="!!busy" @click="action('Refreshing library',refresh)">Refresh library</button><button :aria-pressed="tab==='Versions'" @click="tab=tab==='Versions'?'Aspects':'Versions'">{{tab==='Versions'?'Aspects':'Installed versions'}}</button><span role="status">{{busy}}</span></div>
 </StudioRibbon>
 <p v-if="error" class="error" role="alert">{{error}}</p>
 <div v-if="validation&&!validation.valid" class="error"><button v-for="issue in validation.issues" :key="issue.path+issue.message" @click="locate(issue.path)">{{issue.path}}: {{issue.message}}</button></div>
 <div v-if="tab==='Versions'" class="version-list"><h2>Installed component definitions</h2><p>Versions are immutable. Open one to inspect it or create a new version.</p><p v-if="!records.length">No definitions installed yet.</p><button v-for="record in records" :key="record.definition.id+record.definition.version" @click="load(record)"><strong>{{record.definition.name}} · {{record.definition.version}}</strong><small>{{record.definition.id}} · {{record.definition.aspects.length}} aspects</small></button></div>
 <div v-else-if="tab==='Connections'" class="definition-canvas">
  <h2>Aspect connections</h2><p>Check compatibility to inspect typed ports and dependencies. Links declare exact output-to-input types; they do not yet execute, schedule tasks or deliver messages. Unconnected inputs remain outside this check.</p>
  <div class="connection-form"><label>Source output<select v-model="linkSource"><option value="">Choose output…</option><template v-for="(port,index) in compatibility?.ports" :key="index"><option v-if="port.direction==='output'" :value="String(index)">{{endpointLabel(port)}}</option></template></select></label><label>Target input<select v-model="linkTarget"><option value="">Choose input…</option><template v-for="(port,index) in compatibility?.ports" :key="index"><option v-if="port.direction==='input'" :value="String(index)">{{endpointLabel(port)}}</option></template></select></label><button :disabled="linkSource===''||linkTarget===''||!!busy" @click="addLink">Add link</button></div>
  <p v-if="!draft.links?.length">No declared links. Aspects remain independently usable.</p>
  <article v-for="(link,index) in draft.links" :key="link.id" class="connection-card" :class="{invalid:validation?.issues.some(i=>i.path.startsWith('links['+index+']'))}"><strong>{{link.id}}</strong><p>{{link.source.slot}} / {{link.source.interface}} / {{link.source.port}} → {{link.target.slot}} / {{link.target.interface}} / {{link.target.port}}</p><button @click="draft.links!.splice(index,1)">Remove link</button></article>
  <p v-if="!validation">Draft changed or not checked. Run Check compatibility before installing.</p>
  <details v-if="compatibility"><summary>Dependency occurrences ({{compatibility.dependencies.length}})</summary><p>Installed aspect roots and their embedded or catalog-resolved dependencies. Repeated entries show where a shared dependency is used.</p><div class="dependency-table"><table><thead><tr><th>Path</th><th>Artifact</th><th>Digest</th></tr></thead><tbody><tr v-for="(dep,index) in compatibility.dependencies" :key="index"><td>{{dep.path}}</td><td>{{dep.kind}} · {{dep.id}}@{{dep.version}}</td><td><code>{{dep.digest}}</code></td></tr></tbody></table></div></details>
 </div>
 <div v-else class="definition-canvas">
  <div class="canvas-heading"><div><small>COMPONENT DEFINITION</small><h2>{{draft.name}}</h2><p>{{draft.id}} · {{draft.version}}</p></div><button :aria-expanded="libraryOpen" @click="libraryOpen=!libraryOpen">{{libraryOpen?'Hide aspect library':'Show aspect library'}}</button></div>
  <div class="definition-layout" :class="{wide:!libraryOpen}">
   <aside v-if="libraryOpen" class="aspect-library"><h3>Installed aspects</h3><label>Search<input v-model="search" type="search" placeholder="Name, ID or kind"/></label><p v-if="!available.length">Install an artifact in Data, State, Messages, Workflows or Interface & behavior, then refresh this library.</p><article v-for="entry in available" :key="entry.kind+entry.id+entry.version"><strong>{{entry.name}}</strong><small>{{entry.kind}} · {{entry.version}}</small><button @click="add(entry)">Add aspect</button></article></aside>
   <div class="aspect-cards"><p v-if="!draft.aspects.length" class="empty">No aspects yet. Add only the aspects this component needs.</p><button v-for="(item,index) in draft.aspects" :key="index" class="aspect-card" :class="{selected:index===selected,invalid:validation?.issues.some(i=>i.path.startsWith('aspects['+index+']'))}" @click="selected=index;settings=false"><small>{{item.kind==='component'?'Behavior':item.kind}}</small><strong>{{item.slot}}</strong><span>{{item.id}}</span><span>Version {{item.version}}</span><code>{{item.digest.slice(0,12)}}…</code></button></div>
  </div>
  <CanvasInspector v-if="settings" title="Component identity" @close="settings=false"><label>Name *<input v-model="draft.name"/></label><label>Namespaced ID *<input v-model="draft.id"/></label><label>Version *<input v-model="draft.version"/></label><label>Description<textarea v-model="draft.description" rows="4"/></label><p>Use a new version for changed content. An installed definition cannot be overwritten.</p></CanvasInspector>
  <CanvasInspector v-else-if="aspect" :title="aspect.slot" @close="selected=-1"><label>Aspect slot *<input v-model="aspect.slot"/></label><p><strong>{{aspect.kind}}</strong> · {{aspect.id}}@{{aspect.version}}</p><code class="digest">{{aspect.digest}}</code><label>Replace with an installed artifact<select @change="replace"><option value="">Select an exact version…</option><template v-for="(entry,index) in catalog" :key="entry.kind+entry.id+entry.version"><option v-if="entry.ready&&entry.source==='installed-catalog'" :value="index">{{entry.kind}} · {{entry.name}} · {{entry.version}}</option></template></select></label><button :disabled="!!busy" @click="openAspect">Open aspect editor</button><p>Edits create an artifact draft. Install its new version and explicitly replace this pin to update the component.</p><button @click="draft.aspects.splice(selected,1);selected=-1">Remove aspect</button></CanvasInspector>
 </div>
</section>
</template>
<style scoped>
.connection-form{display:flex;gap:12px;flex-wrap:wrap;align-items:end}.connection-form label{flex:1;min-width:min(240px,100%)}.connection-card{padding:15px;background:#fff;border:1px solid #cbdce3;border-radius:8px;margin:10px 0;overflow-wrap:anywhere}.connection-card.invalid{border-color:#bb4740}.dependency-table{overflow:auto;max-height:360px}.dependency-table table{border-collapse:collapse;width:100%;font-size:11px}.dependency-table td,.dependency-table th{padding:8px;text-align:left;border-bottom:1px solid #ddd;overflow-wrap:anywhere}.dependency-table code{white-space:normal}.definition-workbench{padding:16px;min-width:0;color:#345468}.commands,.canvas-heading{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.canvas-heading{justify-content:space-between;margin-bottom:18px}.canvas-heading h2{margin:5px 0;font-size:20px}.definition-workbench p{font-size:12px;line-height:1.6}.definition-workbench small{font-size:11px;color:#6d8491}.definition-workbench button{font:inherit;font-size:12px;padding:9px 12px;border:1px solid #bfd4cd;border-radius:6px;color:#2b6956;background:#fff;cursor:pointer}.definition-workbench button:hover{background:#eef8f2}.definition-workbench button:focus-visible{outline:2px solid #287862}.definition-workbench button:disabled{opacity:.5;cursor:wait}.definition-canvas{position:relative;min-height:650px;border:1px solid #d5e3e9;border-radius:12px;padding:20px;background:radial-gradient(#d1dee5 1px,transparent 1px) 0 0/20px 20px,#f7fafb}.definition-layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:18px;align-items:start}.definition-layout.wide{grid-template-columns:1fr}.aspect-library{background:#fff;padding:12px;border:1px solid #dae4ea;border-radius:8px;max-height:550px;overflow:auto}.aspect-library h3{font-size:14px}.aspect-library article{display:grid;gap:6px;padding:12px 0;border-top:1px solid #e0e9ee;overflow-wrap:anywhere;font-size:12px}.aspect-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(220px,100%),1fr));gap:15px;min-width:0}.definition-workbench .aspect-card{display:grid;text-align:left;gap:9px;padding:18px;overflow-wrap:anywhere;max-width:340px;border-top:4px solid #438c76}.aspect-card.selected{outline:2px solid #368e74}.aspect-card.invalid{border-color:#bb4740}.definition-workbench label{display:grid;gap:7px;font-size:12px;margin:12px 0;min-width:0}.definition-workbench input,.definition-workbench select,.definition-workbench textarea{box-sizing:border-box;width:100%;min-width:0;max-width:100%;border:1px solid #cbdce3;border-radius:5px;padding:9px;font:inherit;color:#345468}.digest{display:block;overflow-wrap:anywhere;font-size:10px}.error{padding:12px;background:#fff0ef;border:1px solid #efc0bb;color:#a03a34;border-radius:8px;margin:10px 0}.error button{display:block;color:#a03a34;text-align:left;border:0;background:transparent}.empty{padding:45px 20px;text-align:center}.version-list{background:#fff;padding:20px;border:1px solid #d5e3e9;border-radius:10px}.version-list>button{display:grid;gap:6px;text-align:left;margin:10px 0;width:100%;overflow-wrap:anywhere}@media(max-width:800px){.definition-layout{grid-template-columns:1fr}.aspect-library{max-height:230px}.definition-canvas{padding:12px}.definition-workbench{padding:8px}}
</style>
